import React from 'react';
import Navbar from './components/Navbar';
import CorkBoard from './features/wall-todos/CorkBoard';
import { useWorkspaceStore } from './store/useWorkspaceStore';

export default function App() {
  const { activeTab } = useWorkspaceStore();

  return (
    <div className="min-h-screen bg-[var(--color-desk)] flex flex-col">
      <Navbar />
      <main className="flex-1 p-6 flex items-center justify-center">
        {activeTab === 'wall' && <CorkBoard />}
        {activeTab === 'notebook' && (
          <div className="text-white text-center p-12 border border-dashed border-stone-700 rounded-2xl">
            <h2 className="text-xl font-bold">3D Notebook Module</h2>
            <p className="text-stone-400 mt-2 text-sm">Next up: PIN Lock & Flip Pages 📖</p>
          </div>
        )}
        {activeTab === 'notes' && (
          <div className="text-white text-center p-12 border border-dashed border-stone-700 rounded-2xl">
            <h2 className="text-xl font-bold">Quick Notes List Module</h2>
            <p className="text-stone-400 mt-2 text-sm">Simple drawer notes sheet view 📝</p>
          </div>
        )}
      </main>
    </div>
  );
}
